-- A10 Hospital — core relational schema (MySQL 8.4).
--
-- Two databases (schemas) keep data and access separate:
--   a10_hospital  base tables, functions, triggers and stored procedures (private)
--   a10_api       security views the application may read (see 05_views.sql)
-- The application's MySQL account has no privileges on these tables at all (see 06_grants.sql).
--
-- Conventions
--   * Primary keys are UUIDs stored as CHAR(36), generated by DEFAULT (UUID()).
--   * All DATETIME columns hold UTC. The server and every session run with time_zone = '+00:00'.
--   * PostgreSQL arrays from the original design are JSON arrays here.

DROP DATABASE IF EXISTS a10_api;
DROP DATABASE IF EXISTS a10_hospital;
CREATE DATABASE a10_hospital CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
CREATE DATABASE a10_api CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE a10_hospital;

-- ───────────────────────────── Settings ─────────────────────────────
CREATE TABLE settings (
  `key`        VARCHAR(80) PRIMARY KEY,
  value        JSON NOT NULL,
  description  TEXT,
  is_public    BOOLEAN NOT NULL DEFAULT FALSE,
  updated_at   DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3)
);

-- ───────────────────────────── Authentication ─────────────────────────────
-- Accounts and credentials. Password hashes (scrypt) are created by the API server; the
-- application account can never read this table directly.
CREATE TABLE auth_users (
  id                  CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  email               VARCHAR(254) NOT NULL UNIQUE,
  password_hash       VARCHAR(255),
  raw_user_meta_data  JSON NOT NULL DEFAULT (JSON_OBJECT()),
  email_confirmed_at  DATETIME(3),
  created_at          DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
);

-- Signed-in sessions. The browser holds the random token; only its SHA-256 hash is stored.
-- The database derives "who is calling" from this table (see app_uid() in 02_functions.sql).
CREATE TABLE auth_sessions (
  token_hash  CHAR(64) PRIMARY KEY,
  user_id     CHAR(36) NOT NULL,
  created_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  expires_at  DATETIME(3) NOT NULL,
  CONSTRAINT auth_sessions_user_fk FOREIGN KEY (user_id) REFERENCES auth_users (id) ON DELETE CASCADE,
  INDEX auth_sessions_user_idx (user_id)
);

-- Single-use, expiring tokens for email verification and password recovery.
CREATE TABLE auth_tokens (
  token_hash  CHAR(64) PRIMARY KEY,
  user_id     CHAR(36) NOT NULL,
  kind        ENUM('signup', 'recovery') NOT NULL,
  expires_at  DATETIME(3) NOT NULL,
  used_at     DATETIME(3),
  CONSTRAINT auth_tokens_user_fk FOREIGN KEY (user_id) REFERENCES auth_users (id) ON DELETE CASCADE
);

-- Simulated inbox for local development: verification and recovery "emails" are stored here
-- and shown on /dev/mailbox. Nothing is delivered.
CREATE TABLE dev_mailbox (
  id          BIGINT AUTO_INCREMENT PRIMARY KEY,
  to_email    VARCHAR(254) NOT NULL,
  subject     VARCHAR(255) NOT NULL,
  body        TEXT NOT NULL,
  link        VARCHAR(500),
  created_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
);

-- ───────────────────────────── Identity ─────────────────────────────
CREATE TABLE profiles (
  id                       CHAR(36) PRIMARY KEY,
  email                    VARCHAR(254) NOT NULL,
  full_name                VARCHAR(120) NOT NULL DEFAULT '',
  phone                    VARCHAR(20),
  date_of_birth            DATE,
  address                  VARCHAR(400),
  emergency_contact_name   VARCHAR(120),
  emergency_contact_phone  VARCHAR(20),
  blood_group              ENUM('A+','A-','B+','B-','AB+','AB-','O+','O-'),
  is_active                BOOLEAN NOT NULL DEFAULT TRUE,
  is_sample                BOOLEAN NOT NULL DEFAULT FALSE,
  created_at               DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at               DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT profiles_user_fk FOREIGN KEY (id) REFERENCES auth_users (id) ON DELETE CASCADE,
  CONSTRAINT profiles_phone_chk CHECK (phone IS NULL OR REGEXP_LIKE(phone, '^[0-9+() -]{6,20}$')),
  CONSTRAINT profiles_ec_phone_chk CHECK (emergency_contact_phone IS NULL OR REGEXP_LIKE(emergency_contact_phone, '^[0-9+() -]{6,20}$')),
  CONSTRAINT profiles_dob_chk CHECK (date_of_birth IS NULL OR date_of_birth >= '1900-01-01'),
  INDEX profiles_full_name_idx (full_name),
  INDEX profiles_email_idx (email)
);

CREATE TABLE user_roles (
  user_id     CHAR(36) NOT NULL,
  role        ENUM('patient', 'doctor', 'staff', 'admin') NOT NULL,
  granted_by  CHAR(36),
  granted_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (user_id, role),
  CONSTRAINT user_roles_user_fk FOREIGN KEY (user_id) REFERENCES profiles (id) ON DELETE CASCADE,
  CONSTRAINT user_roles_granted_by_fk FOREIGN KEY (granted_by) REFERENCES profiles (id) ON DELETE SET NULL
);

CREATE TABLE staff_permissions (
  user_id     CHAR(36) NOT NULL,
  permission  ENUM('appointments', 'patient_admin', 'lab_records', 'pharmacy') NOT NULL,
  granted_by  CHAR(36),
  granted_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (user_id, permission),
  CONSTRAINT staff_permissions_user_fk FOREIGN KEY (user_id) REFERENCES profiles (id) ON DELETE CASCADE,
  CONSTRAINT staff_permissions_granted_by_fk FOREIGN KEY (granted_by) REFERENCES profiles (id) ON DELETE SET NULL
);

CREATE TABLE employee_invitations (
  id           CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  email        VARCHAR(254) NOT NULL,
  permissions  JSON NOT NULL DEFAULT (JSON_ARRAY()),
  token        CHAR(36) NOT NULL UNIQUE DEFAULT (UUID()),
  invited_by   CHAR(36),
  expires_at   DATETIME(3) NOT NULL DEFAULT (CURRENT_TIMESTAMP(3) + INTERVAL 7 DAY),
  accepted_at  DATETIME(3),
  accepted_by  CHAR(36),
  revoked_at   DATETIME(3),
  created_at   DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  CONSTRAINT invitations_email_chk CHECK (REGEXP_LIKE(email, '^[^@[:space:]]+@[^@[:space:]]+\\.[^@[:space:]]+$')),
  CONSTRAINT invitations_invited_by_fk FOREIGN KEY (invited_by) REFERENCES profiles (id) ON DELETE SET NULL,
  CONSTRAINT invitations_accepted_by_fk FOREIGN KEY (accepted_by) REFERENCES profiles (id) ON DELETE SET NULL,
  INDEX employee_invitations_email_idx (email)
);

-- ───────────────────────────── Organisation ─────────────────────────────
CREATE TABLE departments (
  id               CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  slug             VARCHAR(80) NOT NULL UNIQUE,
  name             VARCHAR(80) NOT NULL,
  summary          VARCHAR(255) NOT NULL DEFAULT '',
  description      TEXT NOT NULL DEFAULT (''),
  icon             VARCHAR(40) NOT NULL DEFAULT 'stethoscope',
  image_url        VARCHAR(255),
  services         JSON NOT NULL DEFAULT (JSON_ARRAY()),
  phone_extension  VARCHAR(20),
  sort_order       INT NOT NULL DEFAULT 100,
  is_active        BOOLEAN NOT NULL DEFAULT TRUE,
  is_sample        BOOLEAN NOT NULL DEFAULT FALSE,
  created_at       DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at       DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT departments_slug_chk CHECK (REGEXP_LIKE(slug, '^[a-z0-9-]+$', 'c')),
  CONSTRAINT departments_name_chk CHECK (CHAR_LENGTH(name) BETWEEN 2 AND 80)
);

CREATE TABLE doctors (
  id                       CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  user_id                  CHAR(36) UNIQUE,
  slug                     VARCHAR(120) NOT NULL UNIQUE,
  full_name                VARCHAR(120) NOT NULL,
  department_id            CHAR(36) NOT NULL,
  speciality               VARCHAR(120) NOT NULL,
  qualifications           JSON NOT NULL DEFAULT (JSON_ARRAY()),
  qualifications_verified  BOOLEAN NOT NULL DEFAULT FALSE,
  licence_number           VARCHAR(60),
  licence_verified         BOOLEAN NOT NULL DEFAULT FALSE,
  years_experience         INT,
  bio                      TEXT NOT NULL DEFAULT (''),
  languages                JSON NOT NULL DEFAULT (JSON_ARRAY()),
  consultation_fee         DECIMAL(10,2),
  consultation_minutes     INT NOT NULL DEFAULT 20,
  photo_url                VARCHAR(255),
  is_active                BOOLEAN NOT NULL DEFAULT TRUE,
  is_sample                BOOLEAN NOT NULL DEFAULT FALSE,
  created_at               DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at               DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT doctors_user_fk FOREIGN KEY (user_id) REFERENCES profiles (id) ON DELETE SET NULL,
  CONSTRAINT doctors_department_fk FOREIGN KEY (department_id) REFERENCES departments (id),
  CONSTRAINT doctors_slug_chk CHECK (REGEXP_LIKE(slug, '^[a-z0-9-]+$', 'c')),
  CONSTRAINT doctors_name_chk CHECK (CHAR_LENGTH(full_name) BETWEEN 2 AND 120),
  CONSTRAINT doctors_experience_chk CHECK (years_experience IS NULL OR years_experience BETWEEN 0 AND 70),
  CONSTRAINT doctors_fee_chk CHECK (consultation_fee IS NULL OR consultation_fee >= 0),
  CONSTRAINT doctors_minutes_chk CHECK (consultation_minutes BETWEEN 5 AND 120),
  INDEX doctors_department_idx (department_id, is_active),
  INDEX doctors_name_idx (full_name)
);

CREATE TABLE doctor_availability (
  id            CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  doctor_id     CHAR(36) NOT NULL,
  weekday       TINYINT NOT NULL COMMENT '0 = Sunday … 6 = Saturday',
  start_time    TIME NOT NULL,
  end_time      TIME NOT NULL,
  slot_minutes  INT NOT NULL DEFAULT 20,
  created_at    DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  CONSTRAINT availability_doctor_fk FOREIGN KEY (doctor_id) REFERENCES doctors (id) ON DELETE CASCADE,
  CONSTRAINT availability_weekday_chk CHECK (weekday BETWEEN 0 AND 6),
  CONSTRAINT availability_slot_chk CHECK (slot_minutes BETWEEN 10 AND 120),
  CONSTRAINT availability_window_chk CHECK (end_time > start_time),
  INDEX doctor_availability_doctor_idx (doctor_id, weekday)
);

CREATE TABLE doctor_applications (
  id                CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  user_id           CHAR(36) NOT NULL UNIQUE,
  full_name         VARCHAR(120) NOT NULL,
  email             VARCHAR(254) NOT NULL,
  phone             VARCHAR(20),
  licence_number    VARCHAR(60) NOT NULL,
  qualifications    JSON NOT NULL DEFAULT (JSON_ARRAY()),
  speciality        VARCHAR(120) NOT NULL,
  department_id     CHAR(36),
  years_experience  INT,
  credential_path   VARCHAR(400),
  status            ENUM('pending', 'approved', 'rejected') NOT NULL DEFAULT 'pending',
  reviewer_id       CHAR(36),
  reviewed_at       DATETIME(3),
  review_notes      TEXT,
  created_at        DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at        DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT applications_user_fk FOREIGN KEY (user_id) REFERENCES profiles (id) ON DELETE CASCADE,
  CONSTRAINT applications_department_fk FOREIGN KEY (department_id) REFERENCES departments (id),
  CONSTRAINT applications_reviewer_fk FOREIGN KEY (reviewer_id) REFERENCES profiles (id) ON DELETE SET NULL,
  CONSTRAINT applications_experience_chk CHECK (years_experience IS NULL OR years_experience BETWEEN 0 AND 70),
  INDEX doctor_applications_status_idx (status, created_at)
);

-- ───────────────────────────── Appointments ─────────────────────────────
CREATE TABLE appointments (
  id                CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  reference         VARCHAR(20) NOT NULL UNIQUE,
  patient_id        CHAR(36) NOT NULL,
  doctor_id         CHAR(36) NOT NULL,
  department_id     CHAR(36) NOT NULL,
  starts_at         DATETIME(3) NOT NULL,
  ends_at           DATETIME(3) NOT NULL,
  status            ENUM('requested', 'confirmed', 'cancelled', 'completed', 'no_show') NOT NULL DEFAULT 'requested',
  reason            VARCHAR(500),
  patient_name      VARCHAR(120) NOT NULL,
  patient_phone     VARCHAR(20),
  patient_email     VARCHAR(254),
  cancel_reason     TEXT,
  rescheduled_from  CHAR(36),
  created_by        CHAR(36),
  is_sample         BOOLEAN NOT NULL DEFAULT FALSE,
  created_at        DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at        DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  -- MySQL has no partial unique indexes. These generated columns hold starts_at only while the
  -- appointment is active (NULL otherwise), and UNIQUE ignores NULLs — so the two keys below
  -- allow one active appointment per doctor (and per patient) per start time.
  active_doctor_slot   DATETIME(3) AS (IF(status IN ('requested', 'confirmed'), starts_at, NULL)) VIRTUAL,
  active_patient_slot  DATETIME(3) AS (IF(status IN ('requested', 'confirmed'), starts_at, NULL)) VIRTUAL,
  CONSTRAINT appointments_patient_fk FOREIGN KEY (patient_id) REFERENCES profiles (id),
  CONSTRAINT appointments_doctor_fk FOREIGN KEY (doctor_id) REFERENCES doctors (id),
  CONSTRAINT appointments_department_fk FOREIGN KEY (department_id) REFERENCES departments (id),
  CONSTRAINT appointments_rescheduled_fk FOREIGN KEY (rescheduled_from) REFERENCES appointments (id) ON DELETE SET NULL,
  CONSTRAINT appointments_created_by_fk FOREIGN KEY (created_by) REFERENCES profiles (id) ON DELETE SET NULL,
  CONSTRAINT appointments_time_chk CHECK (ends_at > starts_at),
  UNIQUE KEY appointments_doctor_slot_uniq (doctor_id, active_doctor_slot),
  UNIQUE KEY appointments_patient_slot_uniq (patient_id, active_patient_slot),
  INDEX appointments_patient_idx (patient_id, starts_at),
  INDEX appointments_doctor_idx (doctor_id, starts_at)
);

CREATE TABLE appointment_events (
  id              BIGINT AUTO_INCREMENT PRIMARY KEY,
  appointment_id  CHAR(36) NOT NULL,
  from_status     ENUM('requested', 'confirmed', 'cancelled', 'completed', 'no_show'),
  to_status       ENUM('requested', 'confirmed', 'cancelled', 'completed', 'no_show') NOT NULL,
  actor_id        CHAR(36),
  note            TEXT,
  created_at      DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  CONSTRAINT appointment_events_appt_fk FOREIGN KEY (appointment_id) REFERENCES appointments (id) ON DELETE CASCADE,
  CONSTRAINT appointment_events_actor_fk FOREIGN KEY (actor_id) REFERENCES profiles (id) ON DELETE SET NULL,
  INDEX appointment_events_appt_idx (appointment_id, created_at)
);

-- ───────────────────────────── Clinical ─────────────────────────────
CREATE TABLE consultations (
  id              CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  appointment_id  CHAR(36) NOT NULL UNIQUE,
  patient_id      CHAR(36) NOT NULL,
  doctor_id       CHAR(36) NOT NULL,
  notes           TEXT NOT NULL DEFAULT (''),
  created_by      CHAR(36),
  is_sample       BOOLEAN NOT NULL DEFAULT FALSE,
  created_at      DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at      DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT consultations_appt_fk FOREIGN KEY (appointment_id) REFERENCES appointments (id),
  CONSTRAINT consultations_patient_fk FOREIGN KEY (patient_id) REFERENCES profiles (id),
  CONSTRAINT consultations_doctor_fk FOREIGN KEY (doctor_id) REFERENCES doctors (id),
  CONSTRAINT consultations_created_by_fk FOREIGN KEY (created_by) REFERENCES profiles (id) ON DELETE SET NULL,
  CONSTRAINT consultations_notes_chk CHECK (CHAR_LENGTH(notes) <= 8000),
  INDEX consultations_patient_idx (patient_id)
);

CREATE TABLE prescriptions (
  id                CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  reference         VARCHAR(20) NOT NULL UNIQUE,
  patient_id        CHAR(36) NOT NULL,
  doctor_id         CHAR(36) NOT NULL,
  appointment_id    CHAR(36),
  consultation_id   CHAR(36),
  status            ENUM('draft', 'issued', 'superseded', 'cancelled') NOT NULL DEFAULT 'draft',
  notes             VARCHAR(2000),
  version           INT NOT NULL DEFAULT 1,
  supersedes_id     CHAR(36),
  amendment_reason  TEXT,
  issued_at         DATETIME(3),
  created_by        CHAR(36),
  is_sample         BOOLEAN NOT NULL DEFAULT FALSE,
  created_at        DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at        DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT prescriptions_patient_fk FOREIGN KEY (patient_id) REFERENCES profiles (id),
  CONSTRAINT prescriptions_doctor_fk FOREIGN KEY (doctor_id) REFERENCES doctors (id),
  CONSTRAINT prescriptions_appt_fk FOREIGN KEY (appointment_id) REFERENCES appointments (id) ON DELETE SET NULL,
  CONSTRAINT prescriptions_consultation_fk FOREIGN KEY (consultation_id) REFERENCES consultations (id) ON DELETE SET NULL,
  CONSTRAINT prescriptions_supersedes_fk FOREIGN KEY (supersedes_id) REFERENCES prescriptions (id) ON DELETE SET NULL,
  CONSTRAINT prescriptions_created_by_fk FOREIGN KEY (created_by) REFERENCES profiles (id) ON DELETE SET NULL,
  INDEX prescriptions_patient_idx (patient_id, created_at),
  INDEX prescriptions_doctor_idx (doctor_id, created_at)
);

-- ───────────────────────────── Pharmacy catalogue ─────────────────────────────
CREATE TABLE medicines (
  id                     CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  slug                   VARCHAR(120) NOT NULL UNIQUE,
  name                   VARCHAR(160) NOT NULL,
  generic_name           VARCHAR(160),
  category               VARCHAR(80) NOT NULL,
  form                   VARCHAR(40) NOT NULL DEFAULT 'Tablet',
  strength               VARCHAR(40),
  pack_size              VARCHAR(60),
  description            TEXT NOT NULL DEFAULT (''),
  price                  DECIMAL(10,2) NOT NULL,
  requires_prescription  BOOLEAN NOT NULL DEFAULT FALSE,
  stock                  INT NOT NULL DEFAULT 0,
  is_active              BOOLEAN NOT NULL DEFAULT TRUE,
  is_sample              BOOLEAN NOT NULL DEFAULT FALSE,
  created_at             DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at             DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT medicines_slug_chk CHECK (REGEXP_LIKE(slug, '^[a-z0-9-]+$', 'c')),
  CONSTRAINT medicines_price_chk CHECK (price >= 0),
  CONSTRAINT medicines_stock_chk CHECK (stock >= 0),
  INDEX medicines_category_idx (category, is_active),
  INDEX medicines_name_idx (name)
);

CREATE TABLE prescription_items (
  id               CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  prescription_id  CHAR(36) NOT NULL,
  medicine_id      CHAR(36),
  medication_name  VARCHAR(160) NOT NULL,
  dosage           VARCHAR(80) NOT NULL,
  frequency        VARCHAR(80) NOT NULL,
  duration         VARCHAR(80) NOT NULL,
  instructions     VARCHAR(500),
  quantity         INT,
  position         INT NOT NULL DEFAULT 0,
  CONSTRAINT prescription_items_rx_fk FOREIGN KEY (prescription_id) REFERENCES prescriptions (id) ON DELETE CASCADE,
  CONSTRAINT prescription_items_medicine_fk FOREIGN KEY (medicine_id) REFERENCES medicines (id) ON DELETE SET NULL,
  CONSTRAINT prescription_items_name_chk CHECK (CHAR_LENGTH(medication_name) >= 1),
  CONSTRAINT prescription_items_dosage_chk CHECK (CHAR_LENGTH(dosage) >= 1),
  CONSTRAINT prescription_items_frequency_chk CHECK (CHAR_LENGTH(frequency) >= 1),
  CONSTRAINT prescription_items_duration_chk CHECK (CHAR_LENGTH(duration) >= 1),
  CONSTRAINT prescription_items_quantity_chk CHECK (quantity IS NULL OR quantity BETWEEN 1 AND 1000),
  INDEX prescription_items_rx_idx (prescription_id, position)
);

CREATE TABLE lab_reports (
  id              CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  reference       VARCHAR(20) NOT NULL UNIQUE,
  patient_id      CHAR(36) NOT NULL,
  doctor_id       CHAR(36),
  department_id   CHAR(36),
  appointment_id  CHAR(36),
  test_name       VARCHAR(160) NOT NULL,
  laboratory      VARCHAR(160) NOT NULL DEFAULT 'A10 Diagnostics Laboratory',
  collected_at    DATETIME(3),
  resulted_at     DATETIME(3),
  status          ENUM('ordered', 'collected', 'in_progress', 'final', 'amended', 'cancelled') NOT NULL DEFAULT 'ordered',
  summary         VARCHAR(2000),
  document_path   VARCHAR(400),
  created_by      CHAR(36),
  is_sample       BOOLEAN NOT NULL DEFAULT FALSE,
  created_at      DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at      DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT lab_reports_patient_fk FOREIGN KEY (patient_id) REFERENCES profiles (id),
  CONSTRAINT lab_reports_doctor_fk FOREIGN KEY (doctor_id) REFERENCES doctors (id) ON DELETE SET NULL,
  CONSTRAINT lab_reports_department_fk FOREIGN KEY (department_id) REFERENCES departments (id) ON DELETE SET NULL,
  CONSTRAINT lab_reports_appt_fk FOREIGN KEY (appointment_id) REFERENCES appointments (id) ON DELETE SET NULL,
  CONSTRAINT lab_reports_created_by_fk FOREIGN KEY (created_by) REFERENCES profiles (id) ON DELETE SET NULL,
  CONSTRAINT lab_reports_test_chk CHECK (CHAR_LENGTH(test_name) >= 2),
  INDEX lab_reports_patient_idx (patient_id, created_at)
);

CREATE TABLE lab_results (
  id               CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  report_id        CHAR(36) NOT NULL,
  analyte          VARCHAR(160) NOT NULL,
  value            VARCHAR(160) NOT NULL,
  unit             VARCHAR(40),
  reference_range  VARCHAR(160) COMMENT 'only populated from the issuing laboratory''s own documented range',
  position         INT NOT NULL DEFAULT 0,
  CONSTRAINT lab_results_report_fk FOREIGN KEY (report_id) REFERENCES lab_reports (id) ON DELETE CASCADE,
  INDEX lab_results_report_idx (report_id, position)
);

CREATE TABLE observation_records (
  id                CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  patient_id        CHAR(36) NOT NULL,
  appointment_id    CHAR(36),
  observed_at       DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  observer_id       CHAR(36) NOT NULL,
  observation_type  VARCHAR(80) NOT NULL,
  value             VARCHAR(500) NOT NULL,
  unit              VARCHAR(40),
  context           VARCHAR(1000),
  is_sample         BOOLEAN NOT NULL DEFAULT FALSE,
  created_at        DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at        DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT observations_patient_fk FOREIGN KEY (patient_id) REFERENCES profiles (id),
  CONSTRAINT observations_appt_fk FOREIGN KEY (appointment_id) REFERENCES appointments (id) ON DELETE SET NULL,
  CONSTRAINT observations_observer_fk FOREIGN KEY (observer_id) REFERENCES profiles (id),
  CONSTRAINT observations_type_chk CHECK (CHAR_LENGTH(observation_type) >= 2),
  CONSTRAINT observations_value_chk CHECK (CHAR_LENGTH(value) >= 1),
  INDEX observation_records_patient_idx (patient_id, observed_at)
);

-- ───────────────────────────── Pharmacy orders ─────────────────────────────
CREATE TABLE medication_orders (
  id                CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  reference         VARCHAR(20) NOT NULL UNIQUE,
  patient_id        CHAR(36) NOT NULL,
  prescription_id   CHAR(36),
  status            ENUM('placed', 'pending_review', 'approved', 'processing', 'dispatched', 'delivered', 'cancelled', 'rejected') NOT NULL DEFAULT 'placed',
  subtotal          DECIMAL(10,2) NOT NULL,
  delivery_fee      DECIMAL(10,2) NOT NULL DEFAULT 0,
  total             DECIMAL(10,2) NOT NULL,
  payment_method    VARCHAR(40) NOT NULL DEFAULT 'cash_on_delivery',
  delivery_address  VARCHAR(400) NOT NULL,
  contact_phone     VARCHAR(20) NOT NULL,
  notes             VARCHAR(500),
  review_note       TEXT,
  reviewer_id       CHAR(36),
  is_sample         BOOLEAN NOT NULL DEFAULT FALSE,
  created_at        DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at        DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT orders_patient_fk FOREIGN KEY (patient_id) REFERENCES profiles (id),
  CONSTRAINT orders_prescription_fk FOREIGN KEY (prescription_id) REFERENCES prescriptions (id) ON DELETE SET NULL,
  CONSTRAINT orders_reviewer_fk FOREIGN KEY (reviewer_id) REFERENCES profiles (id) ON DELETE SET NULL,
  CONSTRAINT orders_amounts_chk CHECK (subtotal >= 0 AND delivery_fee >= 0 AND total >= 0),
  CONSTRAINT orders_address_chk CHECK (CHAR_LENGTH(delivery_address) BETWEEN 5 AND 400),
  CONSTRAINT orders_phone_chk CHECK (REGEXP_LIKE(contact_phone, '^[0-9+() -]{6,20}$')),
  INDEX medication_orders_patient_idx (patient_id, created_at),
  INDEX medication_orders_status_idx (status, created_at)
);

CREATE TABLE medication_order_items (
  id                     CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  order_id               CHAR(36) NOT NULL,
  medicine_id            CHAR(36) NOT NULL,
  name                   VARCHAR(200) NOT NULL,
  unit_price             DECIMAL(10,2) NOT NULL,
  quantity               INT NOT NULL,
  line_total             DECIMAL(10,2) NOT NULL,
  requires_prescription  BOOLEAN NOT NULL DEFAULT FALSE,
  CONSTRAINT order_items_order_fk FOREIGN KEY (order_id) REFERENCES medication_orders (id) ON DELETE CASCADE,
  CONSTRAINT order_items_medicine_fk FOREIGN KEY (medicine_id) REFERENCES medicines (id),
  CONSTRAINT order_items_quantity_chk CHECK (quantity BETWEEN 1 AND 20),
  CONSTRAINT order_items_amounts_chk CHECK (unit_price >= 0 AND line_total >= 0),
  INDEX medication_order_items_order_idx (order_id)
);

CREATE TABLE order_events (
  id           BIGINT AUTO_INCREMENT PRIMARY KEY,
  order_id     CHAR(36) NOT NULL,
  from_status  ENUM('placed', 'pending_review', 'approved', 'processing', 'dispatched', 'delivered', 'cancelled', 'rejected'),
  to_status    ENUM('placed', 'pending_review', 'approved', 'processing', 'dispatched', 'delivered', 'cancelled', 'rejected') NOT NULL,
  actor_id     CHAR(36),
  note         TEXT,
  created_at   DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  CONSTRAINT order_events_order_fk FOREIGN KEY (order_id) REFERENCES medication_orders (id) ON DELETE CASCADE,
  CONSTRAINT order_events_actor_fk FOREIGN KEY (actor_id) REFERENCES profiles (id) ON DELETE SET NULL,
  INDEX order_events_order_idx (order_id, created_at)
);

CREATE TABLE inventory_movements (
  id           BIGINT AUTO_INCREMENT PRIMARY KEY,
  medicine_id  CHAR(36) NOT NULL,
  `change`     INT NOT NULL,
  reason       VARCHAR(255) NOT NULL,
  order_id     CHAR(36),
  actor_id     CHAR(36),
  created_at   DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  CONSTRAINT inventory_medicine_fk FOREIGN KEY (medicine_id) REFERENCES medicines (id) ON DELETE CASCADE,
  CONSTRAINT inventory_order_fk FOREIGN KEY (order_id) REFERENCES medication_orders (id) ON DELETE SET NULL,
  CONSTRAINT inventory_actor_fk FOREIGN KEY (actor_id) REFERENCES profiles (id) ON DELETE SET NULL
);

-- ───────────────────────────── Donations & communications ─────────────────────────────
CREATE TABLE donation_causes (
  id                 CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  slug               VARCHAR(80) NOT NULL UNIQUE,
  title              VARCHAR(160) NOT NULL,
  description        TEXT NOT NULL DEFAULT (''),
  suggested_amounts  JSON NOT NULL DEFAULT (JSON_ARRAY(500, 1000, 2500, 5000)),
  is_active          BOOLEAN NOT NULL DEFAULT TRUE,
  sort_order         INT NOT NULL DEFAULT 100,
  is_sample          BOOLEAN NOT NULL DEFAULT FALSE,
  created_at         DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  CONSTRAINT causes_slug_chk CHECK (REGEXP_LIKE(slug, '^[a-z0-9-]+$', 'c'))
);

CREATE TABLE donations (
  id                  CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  reference           VARCHAR(20) NOT NULL UNIQUE,
  cause_id            CHAR(36) NOT NULL,
  donor_id            CHAR(36),
  donor_name          VARCHAR(120),
  donor_email         VARCHAR(254),
  is_anonymous        BOOLEAN NOT NULL DEFAULT FALSE,
  amount              DECIMAL(10,2) NOT NULL,
  currency            CHAR(3) NOT NULL DEFAULT 'INR',
  message             VARCHAR(500),
  status              ENUM('pending', 'simulated', 'paid', 'failed', 'refunded') NOT NULL DEFAULT 'pending',
  provider            VARCHAR(40) NOT NULL DEFAULT 'demo',
  provider_reference  VARCHAR(120),
  is_sample           BOOLEAN NOT NULL DEFAULT FALSE,
  created_at          DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at          DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT donations_cause_fk FOREIGN KEY (cause_id) REFERENCES donation_causes (id),
  CONSTRAINT donations_donor_fk FOREIGN KEY (donor_id) REFERENCES profiles (id) ON DELETE SET NULL,
  CONSTRAINT donations_amount_chk CHECK (amount BETWEEN 1 AND 1000000),
  INDEX donations_donor_idx (donor_id, created_at),
  INDEX donations_email_idx (donor_email, created_at)
);

CREATE TABLE contact_messages (
  id          CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  name        VARCHAR(120) NOT NULL,
  email       VARCHAR(254) NOT NULL,
  subject     VARCHAR(160) NOT NULL,
  message     TEXT NOT NULL,
  consent     BOOLEAN NOT NULL DEFAULT FALSE,
  status      ENUM('new', 'in_progress', 'closed') NOT NULL DEFAULT 'new',
  created_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  CONSTRAINT contact_name_chk CHECK (CHAR_LENGTH(name) BETWEEN 2 AND 120),
  CONSTRAINT contact_email_chk CHECK (REGEXP_LIKE(email, '^[^@[:space:]]+@[^@[:space:]]+\\.[^@[:space:]]+$')),
  CONSTRAINT contact_subject_chk CHECK (CHAR_LENGTH(subject) BETWEEN 2 AND 160),
  CONSTRAINT contact_message_chk CHECK (CHAR_LENGTH(message) BETWEEN 10 AND 4000),
  INDEX contact_messages_email_idx (email, created_at)
);

CREATE TABLE notifications (
  id          CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  user_id     CHAR(36) NOT NULL,
  kind        VARCHAR(60) NOT NULL,
  title       VARCHAR(160) NOT NULL,
  body        TEXT NOT NULL,
  link        VARCHAR(255),
  read_at     DATETIME(3),
  created_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  CONSTRAINT notifications_user_fk FOREIGN KEY (user_id) REFERENCES profiles (id) ON DELETE CASCADE,
  INDEX notifications_user_idx (user_id, created_at)
);

-- Outgoing email queue. Rows are written in the same transaction as the business change;
-- delivery would happen separately, so a failed send never rolls back an appointment or order.
-- Bodies never contain clinical details.
CREATE TABLE email_outbox (
  id          CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  user_id     CHAR(36),
  to_email    VARCHAR(254) NOT NULL,
  template    VARCHAR(60) NOT NULL,
  subject     VARCHAR(255) NOT NULL,
  body        TEXT NOT NULL,
  status      ENUM('queued', 'sent', 'failed', 'skipped') NOT NULL DEFAULT 'queued',
  attempts    INT NOT NULL DEFAULT 0,
  last_error  TEXT,
  created_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  sent_at     DATETIME(3),
  CONSTRAINT outbox_user_fk FOREIGN KEY (user_id) REFERENCES profiles (id) ON DELETE SET NULL,
  INDEX email_outbox_status_idx (status, created_at)
);

-- Private file storage (lab documents, doctor credentials) kept in the database itself.
-- Paths:  lab-reports/<patient_id>/<report_id>/<file>     credentials/<user_id>/<file>
CREATE TABLE stored_objects (
  bucket      ENUM('lab-reports', 'credentials') NOT NULL,
  name        VARCHAR(400) NOT NULL,
  mime        VARCHAR(120) NOT NULL,
  size        INT NOT NULL,
  data        LONGBLOB NOT NULL,
  owner       CHAR(36),
  created_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (bucket, name),
  CONSTRAINT stored_objects_size_chk CHECK (size <= 10485760)
);

-- ───────────────────────────── Audit ─────────────────────────────
CREATE TABLE audit_logs (
  id          BIGINT AUTO_INCREMENT PRIMARY KEY,
  actor_id    CHAR(36),
  action      VARCHAR(60) NOT NULL,
  entity      VARCHAR(60) NOT NULL,
  entity_id   VARCHAR(80),
  details     JSON NOT NULL DEFAULT (JSON_OBJECT()),
  created_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  INDEX audit_logs_entity_idx (entity, entity_id, created_at),
  INDEX audit_logs_actor_idx (actor_id, created_at)
);
